#' McNemar's ChiSquare Test
#'
#' 
#' @param data .
#' @param rc .
#' @param correct .
#' @param a .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$h0} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
McNemarTest <- function(
    data,
    rc,
    correct = TRUE,
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("McNemarTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rc)) rc <- jmvcore::resolveQuo(jmvcore::enquo(rc))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rc), rc, NULL))


    options <- McNemarTestOptions$new(
        rc = rc,
        correct = correct,
        a = a)

    analysis <- McNemarTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

